<?php
if(!preg_match('/_(test|testing)$/',getenv('DAGRIL_DB_DATABASE')?:''))exit('Test database required');
require __DIR__.'/../app/helpers/functions.php';require __DIR__.'/../app/core/Database.php';require __DIR__.'/../app/core/Model.php';require __DIR__.'/../app/core/Auth.php';require __DIR__.'/../app/models/Livestock.php';
Auth::start();ob_start();$db=Database::getInstance()->connection();$u=$db->query("SELECT u.*,r.slug role_slug FROM users u JOIN roles r ON r.id=u.role_id WHERE r.slug='administrateur' AND u.status='active' LIMIT 1")->fetch();Auth::login($u);Auth::selectSite('all');$site=(int)$db->query("SELECT id FROM sites WHERE code='FARM-MUT'")->fetchColumn();$m=new Livestock();$id=null;$data=['site_id'=>(string)$site,'code'=>'TST-FAC-'.bin2hex(random_bytes(4)),'name'=>'Test unité','facility_type'=>'housing','area_m2'=>'','capacity_heads'=>'100'];
try{$id=$m->createFacility($data);$data['name']='Test unité modifiée';$m->updateFacility($id,$data,$u);$q=$db->prepare('SELECT name FROM livestock_facilities WHERE id=?');$q->execute([$id]);if($q->fetchColumn()!==$data['name'])throw new RuntimeException('Modification absente');foreach([['site_id'=>'99999'],['capacity_heads'=>'-1'],['facility_type'=>'pond','area_m2'=>'0']] as $bad){try{$m->updateFacility($id,array_replace($data,$bad),$u);throw new LogicException('Modification invalide acceptée');}catch(RuntimeException $e){if($e instanceof LogicException)throw $e;}}echo "OK : modification enregistrée, site immuable, capacité et surface contrôlées.\n";}finally{if($id){$q=$db->prepare("DELETE FROM activity_logs WHERE entity_type='livestock_facilities' AND entity_id=?");$q->execute([$id]);$q=$db->prepare('DELETE FROM livestock_facilities WHERE id=?');$q->execute([$id]);}}ob_end_flush();
